def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    bowls = image_patch.find("bowl")
    oranges = image_patch.find("orange")

    if not bowls or not oranges:
        return image_patch

    bowl_oranges = []
    for bowl in bowls:
        orange_in_bowl = [o for o in oranges if bowl.left <= o.left <= bowl.right and bowl.lower <= o.lower <= bowl.upper]
        if orange_in_bowl:
            bowl_oranges.append((bowl, orange_in_bowl))

    if not bowl_oranges:
        return image_patch

    best_bowl = max(bowl_oranges, key=lambda x: sum(o.area for o in x[1]))
    return best_bowl[0]

